Add-Type @"
using System;using System.Text;using System.Runtime.InteropServices;
public static class WG2 { public delegate bool P(IntPtr h,IntPtr l); [DllImport("user32.dll")] static extern bool EnumWindows(P f,IntPtr l); [DllImport("user32.dll")] static extern int GetWindowText(IntPtr h,StringBuilder s,int n); [DllImport("user32.dll")] static extern bool IsWindowVisible(IntPtr h); [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h,int n); [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h); [DllImport("user32.dll")] public static extern bool IsZoomed(IntPtr h); [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow(); public static IntPtr Find(){IntPtr r=IntPtr.Zero;EnumWindows((h,l)=>{if(IsWindowVisible(h)){var s=new StringBuilder(512);GetWindowText(h,s,512);if(s.ToString().Contains("Aura-Farming")||s.ToString().Contains("CatAnimationLab")){r=h;return false;}}return true;},IntPtr.Zero);return r;} public static string Title(IntPtr h){var s=new StringBuilder(512);GetWindowText(h,s,512);return s.ToString();}}
"@
$h=[WG2]::Find();if($h -eq [IntPtr]::Zero){Write-Output "UnityWindowFound=False";exit 2};[WG2]::ShowWindow($h,3)|Out-Null;$fr=[WG2]::SetForegroundWindow($h);Start-Sleep -Milliseconds 250;$mx=[WG2]::IsZoomed($h);$fg=([WG2]::GetForegroundWindow()-eq $h);Write-Output "UnityWindowFound=True";Write-Output ("HWND="+$h);Write-Output ("Title="+[WG2]::Title($h));Write-Output ("ForegroundRequested="+$fr);Write-Output ("ForegroundVerified="+$fg);Write-Output ("MaximizedAfter="+$mx)